123	func (s *Source) getCloudTemplates(
124		ctx context.Context, templateName string,
125		wg *sync.WaitGroup, e env.Env,
126	) {
127		if !e.GetBool(env.DisableRegistryResolve) {
128			s.getRegistryTemplates(ctx, e, templateName)
129			return
130		}
131	
132		// Use the old org templates based API.
133		//
134		// This path can be removed when we are confident in registry resolution. We will
135		// always need to maintain a way to access templates without the service, but we
136		// should only need to maintain one way to access templates through the service.
137		s.getOrgTemplates(ctx, templateName, wg, e)
138	}
139	
140	func (s *Source) getRegistryTemplates(ctx context.Context, e env.Env, templateName string) {
141		r := cmdCmd.NewDefaultRegistry(ctx, cmdBackend.DefaultLoginManager, pkgWorkspace.Instance, nil, cmdutil.Diag(), e)
142	
143		matches, err := NewTemplateMatcher(templateName)
144		if err != nil {
145			s.addError(err)
146			return
147		}
148	
149		for template, err := range r.ListTemplates(ctx, registry.ListTemplatesOptions{}) {
150			if err != nil {
151				s.addError(fmt.Errorf("could not get template: %w", err))
152				return
153			}
154	
155			if template.Source == "github" && strings.HasPrefix(template.Name, "pulumi/templates/") {
156				// These template are maintained using https://github.com/pulumi/templates, and are
157				// ingested without going through the Pulumi Cloud.
158				continue
159			}
160	
161			t := registryTemplate{template, r, s}
162			if !matches(t) {
163				continue
164			}
165	
166			s.addTemplate(t)
167		}
168	}
169	
170	type registryTemplate struct {
171		t        apitype.TemplateMetadata
172		registry registry.Registry
173		source   *Source
174	}
175	
176	var _ Template = registryTemplate{}
177	
178	func (r registryTemplate) Name() string {
179		switch r.t.Source {
180		case "github", "gitlab":
181			parts := strings.SplitN(r.t.Name, "/", 3)
182			return parts[len(parts)-1]
183		default:
184			return r.t.Name
185		}
186	}
