202	func (u *URLInfo) String() string {
203		encodedName := encodeArtifactNamePart(u.Name())
204	
205		if u.Version() == nil {
206			return fmt.Sprintf("registry://%s/%s/%s/%s",
207				u.ResourceType(), u.Source(), u.Publisher(), encodedName)
208		}
209		return fmt.Sprintf("registry://%s/%s/%s/%s@%s",
210			u.ResourceType(), u.Source(), u.Publisher(), encodedName, u.Version().String())
211	}
