// getVersionedRegistryTemplate resolves a template pinned to a specific version through
// the registry's GetTemplate API.
func (s *Source) getVersionedRegistryTemplate(ctx context.Context, r registry.Registry, urlInfo *registry.URLInfo) {
	version := urlInfo.Version()

	// Reconstruct the human-readable identifier (without the version suffix) so it can be
	// resolved to registry coordinates.
	identifier := urlInfo.Name()
	if urlInfo.Publisher() != "" {
		identifier = urlInfo.Publisher() + "/" + identifier
		if urlInfo.Source() != "" {
			identifier = urlInfo.Source() + "/" + identifier
		}
	}

	meta, err := registry.ResolveTemplateFromName(ctx, r, identifier, version)
	if err != nil {
		if errors.Is(err, registry.ErrNotFound) {
			s.addError(fmt.Errorf("template %q version '%s' not found", identifier, version.String()))
			return
		}
		s.addError(err)
		return
	}

	// Version pinning is not supported for VCS-backed templates: their versioning scheme
	// is controlled by the upstream repository rather than the registry.
	if isVCSBackedTemplate(meta) {
		s.addError(fmt.Errorf(
			"template %q is VCS-backed and does not support specific versions", identifier))
		return
	}

	s.addTemplate(registryTemplate{meta, r, s})
}

// isVCSBackedTemplate reports whether the template is backed by a version control system
// (e.g. GitHub or GitLab) rather than the registry itself.
func isVCSBackedTemplate(meta apitype.TemplateMetadata) bool {
	switch meta.Source {
	case "github", "gitlab":
		return true
	}
	return meta.RepoSlug != nil
}

